def factorial_number(n: int) -> float:
    """ Factorial of a non-negative number n.
    """
    if n == 0:
        return 1.0
    else:
        return n * factorial_number(n-1)

def binomial_coefficient(n: int, k: int) -> float:
    """ Binomial coefficient is defined as a number of combinations from n
    different objects with k identical ones. As it is known, the value of
    the binomial coefficient can be decomposed into an integer part and a
    decimal part, where the latter part is the remainder after division of
    the numerator by the denominator.

    For a given value n, the function returns the decimal part of the
    binomial coefficient.
    >>> binomial_coefficient(5, 2)
    0.5
    """
    if n == 0:
        return 0.0
    else:
        return factorial_number(n) / \
                (factorial_number(k) * factorial_number(n-k))


