def parse_nested_parens_with_dfs(paren_string: str) -> List[int]:
    """ Input to this function is a string represented multiple groups for nested parentheses separated by spaces.
    For each of the group, output the deepest level of nesting of parentheses.
    E.g. (()()) has maximum two levels of nesting while ((())) has three.

    >>> parse_nested_parens_with_dfs('(()()) ((())) () ((())()())')
    [2, 3, 1, 3]
    """
    def dfs(current_parens):
        level = 0
        for char in current_parens:
            if char == '(':
                level += 1
            elif char == ')':
                level -= 1
        return level

    if not paren_string:
        return [0]
    paren_groups = paren_string.split(' ')
    return [max(dfs(group)) for group in paren_groups]

