def parse_group_parens(paren_group: str) -> int:
    """ Input to this function is a string represented only a single group of nested parentheses.
    This function will return the maximum level of nesting for that group.
    E.g. (()()) will have two levels of nesting while ((())) has three.
    """
    return 1 + max(map(lambda x: parse_group_parens(x), paren_group.split())) if paren_group else 0

