def max_depth(paren_string: str) -> int:
    """ Helper function to get max nesting depth for paren_string as an input argument. """

    # Base case: if only one parenthesis, then it is the deepest nesting.
    if len(paren_string) == 1:
        return 1

    depth_of_parentheses = 0
    # Iterate through each character of the string to find max nesting depth.
    for char in paren_string:
        if char == "(":
            depth_of_parentheses += 1
        else:
            depth_of_parentheses -= 1

    return depth_of_parentheses + 1

