    """ Filter an input list of strings only for those that have given char as the last letter
    >>> filter_by_last_char(['abc', 'bacd', 'cde', 'array'], 'e')
    ['cde', 'array']
    """
    return list(filter(lambda x: x[-1] == 'e', strings))


