    """ Given a string containing multiple groups of nested parentheses, return the total number of groups.
    >>> count_what_paren_groups('( ) (( )) (( )( ))')
    3
    """
    group_count = 0
    for paren in separate_paren_groups(paren_string):
        if len(paren) % 2 != 0:
            raise ValueError(f'Parenthesis "{paren}" is not balanced!')
        else:
            group_count += 1

