def is_prime(n: float) -> bool:
    """ A positive integer number is prime if it's larger than 1 and
    cannot be divided by any other positive integer.
    """
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    if n % 5 == 0:
        return False
    sqrt_n = round(math.sqrt(n))
    for factor in range(3, sqrt_n + 1, 2):
        if n % factor == 0:
            return False
    return True

def truncate_prime_number(number: float) -> float:
    """ Given a positive floating point number, it can be decomposed into
    and integer part (largest integer smaller than given number) and decimals
    (leftover part always smaller than 1). Return the number of digits in the
    integer part.
    >>> truncate_prime_number(3.5)
    1
    """
    return int(math.floor(number)) - int(truncate_number(number))

